import type { PartOfSpeechValue } from '@englishlearn/db/schemas';
import IRREGULAR from '../../../data/irregular-forms.json';

/**
 * Word forms for the paste import's reverse matcher (B6.7, B6-SPEC §5).
 *
 * Regular forms are generated by spelling rules for the lemma's part of
 * speech — non-words included (`visitting`): a form nobody types never
 * matches anything. Irregular forms come from the WordNet 3.0 exception
 * lists, filtered to our catalogue (data/irregular-forms.json, generated by
 * scripts/build-irregular-forms.py). WordNet leaves rule-shaped plurals out
 * of its lists (`women`, `policemen`): the `-man → -men` rule is here.
 */

/** Text as the matcher compares it: NFC, lower case, straight apostrophes, marks folded. */
export function normalizeTerm(text: string): string {
  return text
    .normalize('NFD')
    .replace(/\p{M}/gu, '')
    .normalize('NFC')
    .toLowerCase()
    .replace(/[‘’‛ʼ`´]/g, "'")
    .split(/\s+/)
    .map((token) => token.replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, ''))
    .filter((token) => token.length > 0)
    .join(' ');
}

const CVC = /(?:^|[^aeiou])[aeiou][b-df-hj-np-tv-z]$/;
const DOUBLES = /[b-df-hj-np-tvz]$/; // w, x, y never double

/** Stems a vowel-initial suffix attaches to: e dropped, final consonant doubled (both kept). */
function vowelStems(w: string): string[] {
  if (w.endsWith('ee') || w.endsWith('oe') || w.endsWith('ye')) return [w];
  if (w.endsWith('e')) return [w.slice(0, -1)];
  if (w.endsWith('c')) return [w, `${w}k`]; // panic -> panicking
  if (CVC.test(w) && DOUBLES.test(w)) return [w, w + w.at(-1)]; // visit / begin: stress unknown
  return [w];
}

/** -s / -es / -ies: a plural, or a verb's third person. */
function sForms(w: string): string[] {
  if (/(?:s|x|z|ch|sh)$/.test(w)) return [`${w}es`];
  if (/[^aeiou]y$/.test(w)) return [`${w.slice(0, -1)}ies`];
  if (/[^aeiou]o$/.test(w)) return [`${w}s`, `${w}es`];
  return [`${w}s`];
}

function verbForms(w: string): string[] {
  const forms = sForms(w);
  if (w.endsWith('ie')) forms.push(`${w.slice(0, -2)}ying`, `${w}d`);
  else if (/[^aeiou]y$/.test(w)) forms.push(`${w}ing`, `${w.slice(0, -1)}ied`);
  else if (w.endsWith('e')) forms.push(...vowelStems(w).map((s) => `${s}ing`), `${w}d`);
  else for (const s of vowelStems(w)) forms.push(`${s}ing`, `${s}ed`);
  return forms;
}

function nounForms(w: string): string[] {
  const forms = sForms(w);
  if (w.endsWith('man')) forms.push(`${w.slice(0, -3)}men`);
  return forms;
}

function comparedForms(w: string): string[] {
  if (/[^aeiou]y$/.test(w)) return [`${w.slice(0, -1)}ier`, `${w.slice(0, -1)}iest`];
  if (w.endsWith('e')) return [`${w}r`, `${w}st`];
  return vowelStems(w).flatMap((s) => [`${s}er`, `${s}est`]);
}

/** One word's regular forms by part of speech (none for closed classes). */
function wordForms(word: string, pos: PartOfSpeechValue): string[] {
  switch (pos) {
    case 'NOUN':
      return nounForms(word);
    case 'VERB':
    case 'PHRASAL_VERB':
      return verbForms(word);
    case 'ADJECTIVE':
    case 'ADVERB':
      return comparedForms(word);
    default:
      return [];
  }
}

/** A multiword lemma inflects its head: a verb its first word, anything else its last. */
function inflectHead(spelling: string, pos: PartOfSpeechValue, forms: (w: string) => string[]) {
  const words = normalizeTerm(spelling).split(' ');
  if (words.length === 1) return forms(words[0] ?? '');
  if (pos === 'VERB' || pos === 'PHRASAL_VERB') {
    const [head = '', ...rest] = words;
    return forms(head).map((f) => [f, ...rest].join(' '));
  }
  const head = words.at(-1) ?? '';
  return forms(head).map((f) => [...words.slice(0, -1), f].join(' '));
}

/** Regular inflections of one spelling of a lemma, normalized; never the spelling itself. */
export function regularForms(spelling: string, pos: PartOfSpeechValue): string[] {
  const own = normalizeTerm(spelling);
  return [...new Set(inflectHead(spelling, pos, (w) => wordForms(w, pos)))].filter(
    (f) => f !== own,
  );
}

type Table = 'verb' | 'noun' | 'adj';
const TABLE_OF: Partial<Record<PartOfSpeechValue, Table>> = {
  VERB: 'verb',
  PHRASAL_VERB: 'verb',
  NOUN: 'noun',
  ADJECTIVE: 'adj',
};

/** base -> its irregular forms, per exception list. */
const IRREGULAR_BY_BASE: Record<Table, ReadonlyMap<string, readonly string[]>> = {
  verb: byBase(IRREGULAR.verb),
  noun: byBase(IRREGULAR.noun),
  adj: byBase(IRREGULAR.adj),
};

function byBase(rows: readonly (readonly string[])[]): Map<string, string[]> {
  const map = new Map<string, string[]>();
  for (const [form, base] of rows) {
    if (form === undefined || base === undefined) continue;
    const forms = map.get(base) ?? [];
    forms.push(normalizeTerm(form));
    map.set(base, forms);
  }
  return map;
}

/** WordNet's irregular forms of one spelling (`went`, `children`; `got up` for `get up`). */
export function irregularForms(spelling: string, pos: PartOfSpeechValue): string[] {
  const table = TABLE_OF[pos];
  if (!table) return [];
  const map = IRREGULAR_BY_BASE[table];
  const own = normalizeTerm(spelling);
  const whole = map.get(own) ?? [];
  const head = inflectHead(spelling, pos, (w) => [...(map.get(w) ?? [])]);
  return [...new Set([...whole, ...head])].filter((f) => f !== own);
}

/** The exception-list rows, for tests built from the data. */
export const IRREGULAR_ROWS: Readonly<Record<Table, readonly (readonly string[])[]>> = IRREGULAR;
